mapper.select:
SELECT r.id,v.title,v.baseline_kind,r.status,r.revision,v.id AS version_id,v.version_number,
  v.interview_id,JSON_UNQUOTE(JSON_EXTRACT(v.interview_json,'$.title')) AS interview_title,r.updated_at
FROM review_recollection r JOIN review_recollection_version v
  ON v.owner_id=r.owner_id AND v.recollection_id=r.id AND v.id=r.current_version_id
WHERE r.owner_id=#{owner} AND r.status=#{status}
AND v.interview_id=#{interviewId}
AND v.title LIKE #{pattern} ESCAPE '!'
AND r.id > #{cursor}
ORDER BY r.id LIMIT #{limit}

SELECT id,version_number AS number,title,created_at FROM review_recollection_version
WHERE owner_id=#{owner} AND recollection_id=#{id}
AND version_number < #{before}
ORDER BY version_number DESC LIMIT #{limit}
